 "content": "def transform(grid):
    import random
    h, w = len(grid), len(grid[0])
    cells = [value for row in grid for value in row]
    seed = 0
    for value in cells:
        seed = (seed * 11 + value + 1) & 0xFFFFFFFF
    rng = random.Random(seed)
    out = [[0] * (2 * w) for _ in range(2 * h)]
    for tr in range(2):
        for tc in range(2):
            tile = cells[:]
            if tr or tc:
                rng.shuffle(tile)
            for i, value in enumerate(tile):
                out[tr * h + i // w][tc * w + i % w] = value
    return out
